chapters=[('sf','01','San Francisco','The bay. The bridge. The open coast.','September 9–12 · 3 nights + onward travel','sf.jpg','Golden Gate Bridge over San Francisco Bay','Three nights in SF, then Santa Cruz and a provisional overnight connection to LA.'),('la','02','Los Angeles','Palm trees, Pacific light.','September 13–15 · 2 nights','la.jpg','Palm-lined Los Angeles streets','Recover after the coach, catch Griffith at sunset and enjoy one full LA day.'),('nyc','03','New York City','The city you already know by heart.','September 15–23 · 8 nights','nyc.jpg','Manhattan skyline across the water','Eight nights for the icons, the neighborhoods and the little things in between.')]


def link(label,url): return f'<a href="{e(url,quote=True)}" target="_blank" rel="noopener noreferrer">{e(label)} <span aria-hidden="true">↗</span></a>'
def render_day(d):
    region,day,title,route,tag,stay,slots,note,backup,places,links=d
    dt=date(2026,9,day)
    timeline=''.join(f'<li><span class="time">{e(t)}</span><div><h4>{e(h)}</h4><p>{e(p)}</p></div></li>' for t,h,p in slots)
    maplinks=''.join(link(p,'https://www.google.com/maps/search/?api=1&query='+quote(p)) for p in places)
    return f'''<details class="day" id="day-{day}" {'open' if day in (9,12,13,15) else ''}>
<summary><span class="date"><b>{day:02}</b><span>SEP · {dt.strftime('%a').upper()}</span></span><span class="day-heading"><span class="day-route">{e(route)}</span><h3>{e(title)}</h3></span><span class="tag">{e(tag)}</span><span class="toggle" aria-hidden="true">+</span></summary>
<div class="day-content"><ol class="timeline">{timeline}</ol><aside class="day-aside"><span class="eyebrow">MAKE IT WORK</span><p>{e(note)}</p><div class="backup"><b>Keep it flexible</b><p>{e(backup)}</p></div><span class="stay">◷ &nbsp; Overnight: {e(stay)}</span></aside><div class="day-links"><div><b>Places on the map</b><div>{maplinks}</div></div>{('<div><b>Plan & book</b><div>'+''.join(link(l,u) for l,u in links)+'</div></div>') if links else ''}</div></div></details>'''

chapterhtml=''
for key,num,name,title,dates,img,alt,intro in chapters:
    chapterhtml+=f'''<section class="chapter" id="{key}" aria-labelledby="heading-{key}"><div class="chapter-head"><div><span class="eyebrow">CHAPTER {num} / {e(dates).upper()}</span><h2 id="heading-{key}">{e(name)}<span class="dot">.</span></h2><p>{e(intro)}</p></div><a class="back" href="#route">Back to route ↑</a></div><div class="chapter-banner"><img src="assets/{img}" alt="{e(alt)}" loading="lazy" width="1600" height="1000"><p>{e(title)}</p></div><div class="day-list">{''.join(render_day(d) for d in days if d[0]==key)}</div></section>'''
