bookinghtml=''.join(f'<article class="booking"><span class="booking-num">{n}</span><span class="eyebrow">{e(dt)}</span><h3>{e(title)}</h3><p>{e(desc)}</p>{link(label,url)}</article>' for n,title,dt,desc,label,url in bookings)
cards=''.join(f'<a class="destination {key}" href="#{key}"><img src="assets/{img}" alt="{e(alt)}" width="1600" height="1000" {"fetchpriority=\"high\"" if key=="sf" else ""}><span class="card-top"><span>CHAPTER {num}</span><span>↗</span></span><span class="card-bottom"><span>{e(dates)}</span><strong>{e(name)}</strong></span></a>' for key,num,name,title,dates,img,alt,intro in chapters)
